public class Main {
    /**
     * 从库存里领走一些，返回结余。
     *
     * @param stock 库存条数
     * @param take 要领走的条数
     * @return 领完剩下的条数；库存不够时按 0 结算，不会出现负数
     */
    static int afterTaking(int stock, int take) {
        return Math.max(0, stock - take);
    }

    public static void main(String[] args) {
        int stock = {s};
        int take = 20;
        System.out.println("库存 " + stock + " 条");
        System.out.println("领完还剩 " + afterTaking(stock, take) + " 条");
    }
}
